import re

def parse_duration(s: str) -> int:
    match = re.match(r'(\d+)([hms])', s)
    if match:
        value, unit = match.groups()
        if unit == 'h':
            return int(value) * 3600
        elif unit == 'm':
            return int(value) * 60
        elif unit == 's':
            return int(value)
    match = re.match(r'(\d+)h(\d+)m(\d+s)?', s)
    if match:
        hours, minutes, seconds = match.groups()
        return int(hours) * 3600 + int(minutes) * 60 + (int(seconds or 0) if seconds else 0)
    raise ValueError("Invalid duration format")
