def parse_duration(s: str) -> int:
    s = s.replace(' ', '')
    units = {'h': 3600, 'm': 60, 's': 1}
    result = 0
    i = 0
    while i < len(s):
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            result += int(s[i:j]) * units[s[j]]
            i = j
        else:
            i += 1
    return result
