def parse_duration(s: str) -> int:
    s = s.replace('h', 'h').replace('m', 'm').replace('s', 's')
    parts = s.split()
    total_seconds = 0
    for part in parts:
        if 'h' in part:
            total_seconds += int(part[:-1]) * 3600
        elif 'm' in part:
            total_seconds += int(part[:-1]) * 60
        elif 's' in part:
            total_seconds += int(part)
    return total_seconds
